import{_ as a,o as e,c as d,ah as l}from"./chunks/framework.DuX8SFU5.js";const p=JSON.parse('{"title":"AM_CAN_LOGGER — регистратор CAN-трафика и вибраций","description":"","frontmatter":{"title":"AM_CAN_LOGGER — регистратор CAN-трафика и вибраций","device":{"name":"AM_CAN_LOGGER","title":"Регистратор CAN-трафика и вибраций","summary":"Автономно записывает CAN-шины машины и вибрации на карту памяти. Ставится силами площадки, ничего не передаёт в шины, по светодиоду видно, идёт ли запись.","status":"prototype","image":"am_can_logger_enclosure.webp","specs":["2 шины CAN","только приём","формат candump","вибрации, IMU","microSD"],"order":3},"pdf":"/pdf/AM_CAN_LOGGER_overview.pdf"},"headers":[],"relativePath":"am_can_logger/index.md","filePath":"am_can_logger/README.md"}'),r={name:"am_can_logger/index.md"};function o(i,t,c,h,n,s){return e(),d("div",null,[...t[0]||(t[0]=[l('<h2 id="зачем" tabindex="-1">Зачем <a class="header-anchor" href="#зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><p>Регистратор даёт полную запись работы машины: что делал оператор и как отвечала машина. Записываются сырые кадры всех подключённых CAN-шин, без расшифровки на устройстве: словарь сигналов можно уточнять потом и перечитывать им уже снятые записи. Вместе с CAN пишутся вибрации, чтобы связывать их с режимами работы машины.</p><h2 id="как-работает" tabindex="-1">Как работает <a class="header-anchor" href="#как-работает" aria-label="Permalink to &quot;Как работает&quot;">​</a></h2><ul><li>При подаче питания регистратор стартует сам, без ноутбука и настройки на месте.</li><li>Он слушает две шины CAN в режиме только приёма: не подтверждает кадры и не выдаёт ошибок, поэтому не влияет на штатную сеть.</li><li>Каждый кадр с меткой времени записывается на карту microSD в стандартном формате <code>candump</code>; новый файл начинается каждые 60 секунд, так что при пропадании питания под угрозой только текущий файл.</li><li>Акселерометр и гироскоп записываются с полной частотой датчика для анализа вибраций.</li><li>Скорость каждой шины задаётся настройкой: автоподбор скорости не используется, потому что ошибка подбора стоит целой сессии.</li><li>Потери кадров считаются по каждой шине и видны в диагностике.</li></ul><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><p>Регистратор ставит механик или инженер площадки по инструкции, без участия разработчиков.</p><ul><li>Подключение к шине — через переходной жгут с обеими половинами штатного разъёма, без разрезания проводки машины.</li><li>Собственный терминатор 120 Ом регистратора отключён: у существующей шины терминация уже есть.</li><li>Питание — от бортовой сети через преобразователь и предохранитель.</li><li>Место — в кабине: там теплее, чем в наружных шкафах, а карта памяти должна быть доступна без разборки панелей.</li></ul><p>В конце смены карта памяти снимается и передаётся на обработку; сеть для работы регистратора не нужна.</p><h2 id="индикация" tabindex="-1">Индикация <a class="header-anchor" href="#индикация" aria-label="Permalink to &quot;Индикация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Состояние</th><th>Что значит</th><th>Светодиод</th></tr></thead><tbody><tr><td>Запись</td><td>Все подключённые шины передают кадры, потерь нет</td><td>зелёный, мигает медленно</td></tr><tr><td>Тишина на шине</td><td>Одна из шин молчит дольше 2 секунд</td><td>жёлтый, мигает медленно</td></tr><tr><td>Потери</td><td>Кадр потерян или запись на карту не удалась за последние 5 секунд</td><td>красный, мигает часто</td></tr></tbody></table><p>Схемы мигания предварительные и будут уточнены после проверки на машине.</p><h2 id="данные" tabindex="-1">Данные <a class="header-anchor" href="#данные" aria-label="Permalink to &quot;Данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Что</th><th>Где на карте</th><th>Чем читать</th></tr></thead><tbody><tr><td>CAN-кадры</td><td><code>candump/sessNNN/can_NNNN.log</code></td><td><code>candump</code>, <code>canplayer</code>, <code>python-can</code>, любой инструмент SocketCAN</td></tr><tr><td>Вибрации и состояние устройства</td><td><code>log/sessNNN/*.ulg</code></td><td><code>pyulog</code>, PlotJuggler</td></tr></tbody></table><p>Файлы можно забрать и без снятия карты: по USB и через беспроводной модуль, который подходит для проверки состояния, но не для выгрузки больших объёмов. При потоке 3 тыс. кадров в секунду запись занимает около 0,5 ГБ в час.</p><h2 id="ограничения-прототипа" tabindex="-1">Ограничения прототипа <a class="header-anchor" href="#ограничения-прототипа" aria-label="Permalink to &quot;Ограничения прототипа&quot;">​</a></h2><ul><li>Две шины CAN на устройство. Для трёх шин нужны два устройства или третий порт через внешний контроллер.</li><li>Гальванической развязки CAN нет.</li><li>Время берётся из часов устройства: без внешнего источника времени метки начинаются с 2000-01-01, а точными остаются интервалы между кадрами. Источник времени выбирается.</li><li>Текстовые метки событий в записи («начало бурения», «замена штанги») запланированы, но пока не реализованы.</li></ul><h2 id="платформа" tabindex="-1">Платформа <a class="header-anchor" href="#платформа" aria-label="Permalink to &quot;Платформа&quot;">​</a></h2><p>Прототип собран на готовом полётном контроллере класса Pixhawk с нашей прошивкой: так его можно изготовить и проверить в короткие сроки на доступном оборудовании. Подробные характеристики и настройки — в <a href="./datasheet">даташите</a>.</p>',18)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
